-- ============================================================================
-- 3. SEED ADMIN AUDIT LOG (24 STATUS TRANSITION RECORDS)
-- ============================================================================
    admin_id, action, target_user_id, target_email, target_name,
    previous_status, new_status, ip_address, created_at
)
SELECT
    1 AS admin_id,
    CASE
        WHEN u.account_status = 'approved' THEN 'APPROVE_USER'
        WHEN u.account_status = 'rejected' THEN 'REJECT_USER'
    END AS action,
    u.id AS target_user_id,
    u.email AS target_email,
    CONCAT(u.first_name, ' ', u.last_name) AS target_name,
    'pending' AS previous_status,
    u.account_status AS new_status,
    CASE MOD(u.id, 3)
        WHEN 0 THEN '192.168.1.105'
        WHEN 1 THEN '10.0.14.22'
        ELSE '2001:0db8:85a3:0000:0000:8a2e:0370:7334'
    END AS ip_address,
    DATE_ADD(u.created_at, INTERVAL 4 HOUR) AS created_at
FROM users u
WHERE u.role = 'user' AND u.account_status IN ('approved', 'rejected');

-- ============================================================================
-- 4. MASTER TEMPLATE TABLES (180 FLASHCARDS & 300-DAY REVIEW HISTORY)
-- ============================================================================
DROP TEMPORARY TABLE IF EXISTS tmp_deck_templates;
CREATE TEMPORARY TABLE tmp_deck_templates (
    deck_idx INT UNSIGNED PRIMARY KEY,
    title VARCHAR(150) NOT NULL,
    cover_image VARCHAR(255) NOT NULL,
    created_days_ago INT UNSIGNED NOT NULL
) ENGINE=Memory;


DROP TEMPORARY TABLE IF EXISTS tmp_card_templates;
CREATE TEMPORARY TABLE tmp_card_templates (
    template_card_id INT UNSIGNED PRIMARY KEY,
    deck_idx INT UNSIGNED NOT NULL,
    card_idx INT UNSIGNED NOT NULL,
    front TEXT NOT NULL,
    back TEXT NOT NULL,
    interval_days INT UNSIGNED NOT NULL,
    next_review_at DATETIME NOT NULL,
    review_count INT UNSIGNED NOT NULL,
    lapses INT UNSIGNED NOT NULL,
    created_at DATETIME NOT NULL,
    updated_at DATETIME NOT NULL,
    deleted_at DATETIME NULL,
    INDEX idx_tmp_deck (deck_idx, card_idx)
) ENGINE=InnoDB;

DROP TEMPORARY TABLE IF EXISTS tmp_review_history_templates;
CREATE TEMPORARY TABLE tmp_review_history_templates (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    template_card_id INT UNSIGNED NOT NULL,
    deck_idx INT UNSIGNED NOT NULL,
    review_day_offset INT UNSIGNED NOT NULL,
    rating ENUM('remembered', 'forgot') NOT NULL,
    previous_interval INT UNSIGNED NOT NULL,
    new_interval INT UNSIGNED NOT NULL,
    response_time_ms INT UNSIGNED NOT NULL,
    reviewed_at DATETIME NOT NULL,
    INDEX idx_tmp_hist_deck_day (deck_idx, review_day_offset)
) ENGINE=InnoDB;



-- ============================================================================
-- 5. CLONE DECKS, FLASHCARDS, 300-DAY SESSIONS/LOGS & RANDOM PRACTICE ACROSS 30 USERS
-- ============================================================================
-- Deterministic arithmetic ID mapping avoids cursor loops and executes in seconds:
--   * For user_id u (2..31), user_idx = u - 2 (0..29):
--   * deck_id = (user_idx * 6) + deck_idx (1..180)
--   * card_id = (user_idx * 180) + template_card_id (1..5400)

-- 5A. Insert 180 Decks (6 Decks x 30 Standard Users)
SELECT
    ((u.id - 2) * 6) + dt.deck_idx AS id,
    u.id AS user_id,
    dt.title,
    dt.cover_image,
    DATE_SUB(@ref_now, INTERVAL dt.created_days_ago DAY) AS created_at,
    DATE_SUB(@ref_now, INTERVAL 1 DAY) AS updated_at,
    NULL AS deleted_at
FROM users u
CROSS JOIN tmp_deck_templates dt
WHERE u.role = 'user'
ORDER BY id;

-- 5B. Insert 5,400 Flashcards (30 Cards x 6 Decks x 30 Users)
-- Every identical front/back card across all 30 users receives the exact same
-- interval_days, next_review_at, review_count, lapses, created_at, and deleted_at!
    id, deck_id, front, back, interval_days, next_review_at,
    review_count, lapses, created_at, updated_at, deleted_at
)
SELECT
    ((u.id - 2) * 180) + ct.template_card_id AS id,
    ((u.id - 2) * 6) + ct.deck_idx AS deck_id,
    ct.front,
    ct.back,
    ct.interval_days,
    ct.next_review_at,
    ct.review_count,
    ct.lapses,
    ct.created_at,
    ct.updated_at,
    ct.deleted_at
FROM users u
CROSS JOIN tmp_card_templates ct
WHERE u.role = 'user'
ORDER BY id;

-- 5C. Build Distinct Daily Deck Sessions Template & Clone Across 30 Users
DROP TEMPORARY TABLE IF EXISTS tmp_session_templates;
CREATE TEMPORARY TABLE tmp_session_templates (
    template_session_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    deck_idx INT UNSIGNED NOT NULL,
    review_day_offset INT UNSIGNED NOT NULL,
    started_at DATETIME NOT NULL,
    ended_at DATETIME NOT NULL,
    total_reviewed INT UNSIGNED NOT NULL,
    remembered_count INT UNSIGNED NOT NULL,
    UNIQUE KEY uk_deck_day (deck_idx, review_day_offset)
) ENGINE=InnoDB;

SELECT
    deck_idx,
    review_day_offset,
    MIN(reviewed_at) AS started_at,
    DATE_ADD(MAX(reviewed_at), INTERVAL 45 SECOND) AS ended_at,
    COUNT(*) AS total_reviewed,
    SUM(CASE WHEN rating = 'remembered' THEN 1 ELSE 0 END) AS remembered_count
FROM tmp_review_history_templates
GROUP BY deck_idx, review_day_offset
ORDER BY review_day_offset DESC, deck_idx ASC;

SET @session_cnt = (SELECT COUNT(*) FROM tmp_session_templates);

    id, user_id, deck_id, started_at, ended_at, total_reviewed, remembered_count
)
SELECT
    ((u.id - 2) * @session_cnt) + st.template_session_id AS id,
    u.id AS user_id,
    ((u.id - 2) * 6) + st.deck_idx AS deck_id,
    st.started_at,
    st.ended_at,
    st.total_reviewed,
    st.remembered_count
FROM users u
CROSS JOIN tmp_session_templates st
WHERE u.role = 'user'
ORDER BY id;

-- 5D. Insert All 300-Day Review Logs Across 30 Users
    session_id, card_id, rating, previous_interval,
    new_interval, response_time_ms, reviewed_at
)
SELECT
    ((u.id - 2) * @session_cnt) + st.template_session_id AS session_id,
    ((u.id - 2) * 180) + rht.template_card_id AS card_id,
    rht.rating,
    rht.previous_interval,
    rht.new_interval,
    rht.response_time_ms,
    rht.reviewed_at
FROM users u
CROSS JOIN tmp_review_history_templates rht
INNER JOIN tmp_session_templates st
    ON st.deck_idx = rht.deck_idx
   AND st.review_day_offset = rht.review_day_offset
WHERE u.role = 'user'
ORDER BY session_id, rht.reviewed_at;

-- 5E. Seed Random Practice Sessions (12 Non-SRS Cramming Sessions x 30 Users = 360 Rows)
    user_id, deck_id, label, total_rated, remembered_count,
    accuracy_percentage, duration_seconds, started_at, ended_at, created_at
)
SELECT
    u.id AS user_id,
    ((u.id - 2) * 6) + dt.deck_idx AS deck_id,
    CASE WHEN seq.n = 1 THEN 'Midterm Exam Cram' ELSE 'Quick Random Practice' END AS label,
    30 AS total_rated,
    24 + MOD(dt.deck_idx + seq.n, 6) AS remembered_count,
    ROUND(((24 + MOD(dt.deck_idx + seq.n, 6)) / 30.0) * 100, 2) AS accuracy_percentage,
    420 + (dt.deck_idx * 35) AS duration_seconds,
    DATE_SUB(@ref_now, INTERVAL (dt.deck_idx * 12 * seq.n) DAY) AS started_at,
    DATE_ADD(DATE_SUB(@ref_now, INTERVAL (dt.deck_idx * 12 * seq.n) DAY), INTERVAL (420 + (dt.deck_idx * 35)) SECOND) AS ended_at,
    DATE_ADD(DATE_SUB(@ref_now, INTERVAL (dt.deck_idx * 12 * seq.n) DAY), INTERVAL (420 + (dt.deck_idx * 35)) SECOND) AS created_at
FROM users u
CROSS JOIN tmp_deck_templates dt
CROSS JOIN (SELECT 1 AS n UNION ALL SELECT 2 AS n) seq
WHERE u.role = 'user'
ORDER BY u.id, dt.deck_idx, seq.n;

-- Cleanup temporary tables
DROP TEMPORARY TABLE IF EXISTS tmp_review_history_templates;
DROP TEMPORARY TABLE IF EXISTS tmp_session_templates;
DROP TEMPORARY TABLE IF EXISTS tmp_card_templates;
DROP TEMPORARY TABLE IF EXISTS tmp_deck_templates;

-- Refresh optimizer table statistics for accurate EXPLAIN ANALYZE plans
ANALYZE TABLE users, user_settings, admin_audit_log, decks, flashcards, review_sessions, review_logs, random_practice_sessions;
