INSERT INTO tmp_card_templates (template_card_id, deck_idx, card_idx, front, back, interval_days, next_review_at, review_count, lapses, created_at, updated_at, deleted_at) VALUES
(1, 1, 1, 'What does ACID stand for in database transactions?', 'Atomicity, Consistency, Isolation, and Durability.', 256, DATE_ADD(@ref_now, INTERVAL 211 DAY), 8, 0, DATE_SUB(@ref_now, INTERVAL 300 DAY), DATE_SUB(@ref_now, INTERVAL 45 DAY), NULL),
(2, 1, 2, 'Define First Normal Form (1NF).', 'A relation is in 1NF if all attributes contain only atomic (indivisible) values and there are no repeating groups.', 256, DATE_ADD(@ref_now, INTERVAL 213 DAY), 8, 0, DATE_SUB(@ref_now, INTERVAL 298 DAY), DATE_SUB(@ref_now, INTERVAL 43 DAY), NULL),
(3, 1, 3, 'Define Second Normal Form (2NF).', 'A table is in 2NF if it is in 1NF and every non-prime attribute is fully functionally dependent on the whole candidate key (no partial dependencies).', 128, DATE_SUB(@ref_now, INTERVAL 2 DAY), 7, 0, DATE_SUB(@ref_now, INTERVAL 260 DAY), DATE_SUB(@ref_now, INTERVAL 130 DAY), NULL),
(4, 1, 4, 'Define Third Normal Form (3NF).', 'A table is in 3NF if it is in 2NF and has no transitive functional dependencies on the primary key.', 128, DATE_ADD(@ref_now, INTERVAL 78 DAY), 9, 1, DATE_SUB(@ref_now, INTERVAL 280 DAY), DATE_SUB(@ref_now, INTERVAL 50 DAY), NULL),
(5, 1, 5, 'What is Boyce-Codd Normal Form (BCNF)?', 'A stricter version of 3NF where for every non-trivial functional dependency X -> Y, X must be a superkey.', 128, DATE_ADD(@ref_now, INTERVAL 95 DAY), 7, 0, DATE_SUB(@ref_now, INTERVAL 240 DAY), DATE_SUB(@ref_now, INTERVAL 33 DAY), NULL),
(6, 1, 6, 'What is a Primary Key?', 'A minimal set of attributes that uniquely identifies each tuple (row) in a table and cannot contain NULL values.', 64, DATE_SUB(@ref_now, INTERVAL 4 DAY), 6, 0, DATE_SUB(@ref_now, INTERVAL 195 DAY), DATE_SUB(@ref_now, INTERVAL 68 DAY), NULL),
(7, 1, 7, 'What is a Foreign Key?', 'An attribute or set of attributes in one table that references the primary key of another (or the same) table to enforce referential integrity.', 64, DATE_ADD(@ref_now, INTERVAL 39 DAY), 8, 1, DATE_SUB(@ref_now, INTERVAL 225 DAY), DATE_SUB(@ref_now, INTERVAL 25 DAY), NULL),
(8, 1, 8, 'Differentiate between INNER JOIN and LEFT JOIN.', 'INNER JOIN returns only matching rows from both tables; LEFT JOIN returns all rows from the left table and matched rows from the right (or NULL if unmatched).', 64, DATE_ADD(@ref_now, INTERVAL 46 DAY), 6, 0, DATE_SUB(@ref_now, INTERVAL 165 DAY), DATE_SUB(@ref_now, INTERVAL 18 DAY), NULL),
(9, 1, 9, 'What is a Clustered Index?', 'An index that defines the physical storage order of data rows in a table; a table can have only one clustered index (typically the Primary Key in InnoDB).', 64, DATE_ADD(@ref_now, INTERVAL 52 DAY), 10, 2, DATE_SUB(@ref_now, INTERVAL 270 DAY), DATE_SUB(@ref_now, INTERVAL 12 DAY), NULL),
(10, 1, 10, 'What is a Non-Clustered (Secondary) Index?', 'A separate data structure containing indexed column values and pointers (or primary key values) to the actual table rows.', 64, DATE_SUB(@ref_now, INTERVAL 1 DAY), 6, 0, DATE_SUB(@ref_now, INTERVAL 180 DAY), DATE_SUB(@ref_now, INTERVAL 65 DAY), NULL),
(11, 1, 11, 'What is the CAP Theorem in distributed databases?', 'A distributed data store can simultaneously provide at most two of three guarantees: Consistency, Availability, and Partition Tolerance.', 64, DATE_ADD(@ref_now, INTERVAL 29 DAY), 6, 0, DATE_SUB(@ref_now, INTERVAL 155 DAY), DATE_SUB(@ref_now, INTERVAL 35 DAY), NULL),
(12, 1, 12, 'What is a Dirty Read in concurrency control?', 'When a transaction reads data that has been modified by another concurrent transaction but not yet committed.', 32, DATE_SUB(@ref_now, INTERVAL 3 DAY), 5, 0, DATE_SUB(@ref_now, INTERVAL 140 DAY), DATE_SUB(@ref_now, INTERVAL 35 DAY), NULL),
(13, 1, 13, 'What is a Phantom Read?', 'When a transaction re-executes a query returning a set of rows and finds that additional rows satisfying the condition have been inserted by another committed transaction.', 32, DATE_ADD(@ref_now, INTERVAL 18 DAY), 7, 1, DATE_SUB(@ref_now, INTERVAL 150 DAY), DATE_SUB(@ref_now, INTERVAL 14 DAY), NULL),
(14, 1, 14, 'Which SQL isolation level prevents dirty reads, non-repeatable reads, and phantom reads?', 'SERIALIZABLE (though InnoDB also prevents phantom reads in REPEATABLE READ using next-key locking).', 32, DATE_ADD(@ref_now, INTERVAL 22 DAY), 5, 0, DATE_SUB(@ref_now, INTERVAL 130 DAY), DATE_SUB(@ref_now, INTERVAL 10 DAY), NULL),
(15, 1, 15, 'What is Denormalization and when is it used?', 'The intentional introduction of redundancy into a normalized schema to improve read query performance by reducing complex joins.', 32, DATE_ADD(@ref_now, INTERVAL 0 DAY), 7, 1, DATE_SUB(@ref_now, INTERVAL 145 DAY), DATE_SUB(@ref_now, INTERVAL 32 DAY), NULL),
(16, 1, 16, 'Explain the difference between OLTP and OLAP.', 'OLTP (Online Transaction Processing) handles high-volume short transactional queries; OLAP (Online Analytical Processing) handles complex aggregated historical queries.', 32, DATE_ADD(@ref_now, INTERVAL 11 DAY), 5, 0, DATE_SUB(@ref_now, INTERVAL 125 DAY), DATE_SUB(@ref_now, INTERVAL 21 DAY), NULL),
(17, 1, 17, 'What is a Database View?', 'A virtual table defined by a stored SQL query that dynamically pulls data from underlying base tables.', 32, DATE_ADD(@ref_now, INTERVAL 25 DAY), 9, 2, DATE_SUB(@ref_now, INTERVAL 175 DAY), DATE_SUB(@ref_now, INTERVAL 7 DAY), NULL),
(18, 1, 18, 'What is a Stored Procedure?', 'A precompiled collection of SQL statements and control-of-flow logic stored and executed on the database server.', 32, DATE_ADD(@ref_now, INTERVAL 16 DAY), 5, 0, DATE_SUB(@ref_now, INTERVAL 120 DAY), DATE_SUB(@ref_now, INTERVAL 16 DAY), NULL),
(19, 1, 19, 'What is a Database Trigger?', 'A procedural code block that automatically executes in response to specific INSERT, UPDATE, or DELETE events on a table.', 16, DATE_SUB(@ref_now, INTERVAL 2 DAY), 4, 0, DATE_SUB(@ref_now, INTERVAL 85 DAY), DATE_SUB(@ref_now, INTERVAL 18 DAY), NULL),
(20, 1, 20, 'What is Referential Integrity?', 'A relational constraint ensuring that every foreign key value either matches an existing primary key value in the parent table or is NULL.', 16, DATE_ADD(@ref_now, INTERVAL 9 DAY), 6, 1, DATE_SUB(@ref_now, INTERVAL 90 DAY), DATE_SUB(@ref_now, INTERVAL 7 DAY), NULL),
(21, 1, 21, 'What is a Surrogate Key vs. a Natural Key?', 'A surrogate key is a system-generated artificial identifier (e.g., AUTO_INCREMENT id), whereas a natural key is formed from real-world domain attributes (e.g., email or SSN).', 16, DATE_ADD(@ref_now, INTERVAL 12 DAY), 4, 0, DATE_SUB(@ref_now, INTERVAL 65 DAY), DATE_SUB(@ref_now, INTERVAL 4 DAY), NULL),
(22, 1, 22, 'What is Two-Phase Locking (2PL)?', 'A concurrency control protocol with a Growing Phase (acquiring locks without releasing any) and a Shrinking Phase (releasing locks without acquiring any).', 8, DATE_SUB(@ref_now, INTERVAL 1 DAY), 5, 1, DATE_SUB(@ref_now, INTERVAL 50 DAY), DATE_SUB(@ref_now, INTERVAL 9 DAY), NULL),
(23, 1, 23, 'What is a Deadlock in a DBMS?', 'A state where two or more transactions are permanently blocked because each is waiting for a lock held by the other.', 8, DATE_ADD(@ref_now, INTERVAL 5 DAY), 5, 1, DATE_SUB(@ref_now, INTERVAL 40 DAY), DATE_SUB(@ref_now, INTERVAL 3 DAY), NULL),
(24, 1, 24, 'What is Write-Ahead Logging (WAL)?', 'A durability mechanism where all modifications are written to a persistent redo log on disk before the actual data pages are updated.', 4, DATE_SUB(@ref_now, INTERVAL 1 DAY), 2, 0, DATE_SUB(@ref_now, INTERVAL 22 DAY), DATE_SUB(@ref_now, INTERVAL 5 DAY), NULL),
(25, 1, 25, 'Differentiate between DELETE, TRUNCATE, and DROP.', 'DELETE removes filtered rows (DML, logged row-by-row); TRUNCATE resets the table removing all rows quickly (DDL); DROP removes the entire table structure and data (DDL).', 2, DATE_ADD(@ref_now, INTERVAL 1 DAY), 3, 1, DATE_SUB(@ref_now, INTERVAL 18 DAY), DATE_SUB(@ref_now, INTERVAL 1 DAY), NULL),
(26, 1, 26, 'What is a Composite Index and the Leftmost Prefix Rule?', 'An index on multiple columns (A, B, C) that can optimize queries filtering on (A), (A, B), or (A, B, C), but not (B, C) alone.', 2, DATE_ADD(@ref_now, INTERVAL 2 DAY), 1, 0, DATE_SUB(@ref_now, INTERVAL 10 DAY), DATE_SUB(@ref_now, INTERVAL 0 DAY), NULL),
(27, 1, 27, 'What is Entity-Relationship (ER) Cardinality?', 'Specifies the numerical relationship between occurrences of one entity and occurrences of another (1:1, 1:N, M:N).', 1, DATE_ADD(@ref_now, INTERVAL 0 DAY), 3, 2, DATE_SUB(@ref_now, INTERVAL 14 DAY), DATE_SUB(@ref_now, INTERVAL 1 DAY), NULL),
(28, 1, 28, 'How do you implement a Many-to-Many (M:N) relationship in a relational schema?', 'By creating an associative (junction/bridge) table containing foreign keys referencing the primary keys of both related tables.', 1, DATE_ADD(@ref_now, INTERVAL 0 DAY), 0, 0, DATE_SUB(@ref_now, INTERVAL 3 DAY), DATE_SUB(@ref_now, INTERVAL 3 DAY), NULL),
(29, 1, 29, 'What is Database Sharding?', 'Horizontal partitioning of data across multiple independent database server instances to scale out write and read capacity.', 1, DATE_ADD(@ref_now, INTERVAL 0 DAY), 0, 0, DATE_SUB(@ref_now, INTERVAL 1 DAY), DATE_SUB(@ref_now, INTERVAL 1 DAY), NULL),
(30, 1, 30, 'What is SQL Injection (SQLi) and how is it prevented?', 'A vulnerability where untrusted input alters SQL structure; prevented primarily by using prepared statements with parameterized queries.', 8, DATE_SUB(@ref_now, INTERVAL 110 DAY), 5, 1, DATE_SUB(@ref_now, INTERVAL 160 DAY), DATE_SUB(@ref_now, INTERVAL 15 DAY), DATE_SUB(@ref_now, INTERVAL 15 DAY)),
(31, 2, 1, 'What are the four main pillars of Object-Oriented Programming?', 'Encapsulation, Abstraction, Inheritance, and Polymorphism.', 256, DATE_ADD(@ref_now, INTERVAL 212 DAY), 8, 0, DATE_SUB(@ref_now, INTERVAL 300 DAY), DATE_SUB(@ref_now, INTERVAL 44 DAY), NULL),
(32, 2, 2, 'Define Encapsulation in OOP.', 'Bundling data (fields) and methods that operate on that data within a single unit (class) while restricting direct external access to internal state.', 256, DATE_ADD(@ref_now, INTERVAL 214 DAY), 8, 0, DATE_SUB(@ref_now, INTERVAL 297 DAY), DATE_SUB(@ref_now, INTERVAL 42 DAY), NULL),
(33, 2, 3, 'Define Abstraction in OOP.', 'Hiding complex internal implementation details and exposing only the essential features and interfaces to the user.', 128, DATE_SUB(@ref_now, INTERVAL 2 DAY), 7, 0, DATE_SUB(@ref_now, INTERVAL 259 DAY), DATE_SUB(@ref_now, INTERVAL 130 DAY), NULL),
(34, 2, 4, 'Define Inheritance in OOP.', 'A mechanism where a subclass (derived class) acquires properties and behaviors from a superclass (base class), promoting code reuse.', 128, DATE_ADD(@ref_now, INTERVAL 78 DAY), 9, 1, DATE_SUB(@ref_now, INTERVAL 279 DAY), DATE_SUB(@ref_now, INTERVAL 50 DAY), NULL),
(35, 2, 5, 'Define Polymorphism in OOP.', 'The ability of different objects to respond to the same method call or interface in their own specific way (compile-time overloading and runtime overriding).', 128, DATE_ADD(@ref_now, INTERVAL 95 DAY), 7, 0, DATE_SUB(@ref_now, INTERVAL 239 DAY), DATE_SUB(@ref_now, INTERVAL 33 DAY), NULL),
(36, 2, 6, 'Differentiate between Method Overloading and Method Overriding.', 'Overloading defines multiple methods with the same name but different parameter signatures in the same class; Overriding redefines an inherited superclass method in a subclass.', 64, DATE_SUB(@ref_now, INTERVAL 4 DAY), 6, 0, DATE_SUB(@ref_now, INTERVAL 194 DAY), DATE_SUB(@ref_now, INTERVAL 68 DAY), NULL),
(37, 2, 7, 'What is an Abstract Class?', 'A class that cannot be instantiated directly and may contain both abstract methods (without body) and concrete methods.', 64, DATE_ADD(@ref_now, INTERVAL 39 DAY), 8, 1, DATE_SUB(@ref_now, INTERVAL 224 DAY), DATE_SUB(@ref_now, INTERVAL 25 DAY), NULL),
(38, 2, 8, 'What is an Interface in OOP?', 'A contract specifying a set of method signatures that implementing classes must provide, supporting multiple inheritance of type.', 64, DATE_ADD(@ref_now, INTERVAL 46 DAY), 6, 0, DATE_SUB(@ref_now, INTERVAL 164 DAY), DATE_SUB(@ref_now, INTERVAL 18 DAY), NULL),
(39, 2, 9, 'What does the \'S\' in SOLID stand for?', 'Single Responsibility Principle (SRP): A class should have only one reason to change.', 64, DATE_ADD(@ref_now, INTERVAL 52 DAY), 10, 2, DATE_SUB(@ref_now, INTERVAL 269 DAY), DATE_SUB(@ref_now, INTERVAL 12 DAY), NULL),
(40, 2, 10, 'What does the \'O\' in SOLID stand for?', 'Open/Closed Principle (OCP): Software entities should be open for extension, but closed for modification.', 64, DATE_SUB(@ref_now, INTERVAL 1 DAY), 6, 0, DATE_SUB(@ref_now, INTERVAL 179 DAY), DATE_SUB(@ref_now, INTERVAL 65 DAY), NULL),
(41, 2, 11, 'What does the \'L\' in SOLID stand for?', 'Liskov Substitution Principle (LSP): Subtypes must be substitutable for their base types without altering program correctness.', 64, DATE_ADD(@ref_now, INTERVAL 29 DAY), 6, 0, DATE_SUB(@ref_now, INTERVAL 154 DAY), DATE_SUB(@ref_now, INTERVAL 35 DAY), NULL),
(42, 2, 12, 'What does the \'I\' in SOLID stand for?', 'Interface Segregation Principle (ISP): Clients should not be forced to depend on interfaces they do not use.', 32, DATE_SUB(@ref_now, INTERVAL 3 DAY), 5, 0, DATE_SUB(@ref_now, INTERVAL 139 DAY), DATE_SUB(@ref_now, INTERVAL 35 DAY), NULL),
(43, 2, 13, 'What does the \'D\' in SOLID stand for?', 'Dependency Inversion Principle (DIP): High-level modules should not depend on low-level modules; both should depend on abstractions.', 32, DATE_ADD(@ref_now, INTERVAL 18 DAY), 7, 1, DATE_SUB(@ref_now, INTERVAL 149 DAY), DATE_SUB(@ref_now, INTERVAL 14 DAY), NULL),
(44, 2, 14, 'Why is \'Composition over Inheritance\' often recommended?', 'Composition provides greater runtime flexibility, looser coupling, and avoids fragile base class problems inherent in deep inheritance hierarchies.', 32, DATE_ADD(@ref_now, INTERVAL 22 DAY), 5, 0, DATE_SUB(@ref_now, INTERVAL 129 DAY), DATE_SUB(@ref_now, INTERVAL 10 DAY), NULL),
(45, 2, 15, 'What is a Constructor and when is it invoked?', 'A special initialization method invoked automatically when a new instance of a class is allocated.', 32, DATE_ADD(@ref_now, INTERVAL 0 DAY), 7, 1, DATE_SUB(@ref_now, INTERVAL 144 DAY), DATE_SUB(@ref_now, INTERVAL 32 DAY), NULL),
(46, 2, 16, 'What is the difference between Association, Aggregation, and Composition?', 'Association is a general link; Aggregation is a weak \'has-a\' relationship where parts survive the whole; Composition is a strong \'owns-a\' relationship where parts die with the whole.', 32, DATE_ADD(@ref_now, INTERVAL 11 DAY), 5, 0, DATE_SUB(@ref_now, INTERVAL 124 DAY), DATE_SUB(@ref_now, INTERVAL 21 DAY), NULL),
(47, 2, 17, 'What is the Singleton Design Pattern?', 'A creational pattern that restricts instantiation of a class to a single object instance and provides a global access point to it.', 32, DATE_ADD(@ref_now, INTERVAL 25 DAY), 9, 2, DATE_SUB(@ref_now, INTERVAL 174 DAY), DATE_SUB(@ref_now, INTERVAL 7 DAY), NULL),
(48, 2, 18, 'What is the Factory Method Design Pattern?', 'A creational pattern that defines an interface for creating an object, but lets subclasses decide which class to instantiate.', 32, DATE_ADD(@ref_now, INTERVAL 16 DAY), 5, 0, DATE_SUB(@ref_now, INTERVAL 119 DAY), DATE_SUB(@ref_now, INTERVAL 16 DAY), NULL),
(49, 2, 19, 'What is the Observer Design Pattern?', 'A behavioral pattern where an object (Subject) maintains a list of dependents (Observers) and notifies them automatically of any state changes.', 16, DATE_SUB(@ref_now, INTERVAL 2 DAY), 4, 0, DATE_SUB(@ref_now, INTERVAL 84 DAY), DATE_SUB(@ref_now, INTERVAL 18 DAY), NULL),
(50, 2, 20, 'What is the Strategy Design Pattern?', 'A behavioral pattern that defines a family of interchangeable algorithms and encapsulates each one so they can be swapped at runtime.', 16, DATE_ADD(@ref_now, INTERVAL 9 DAY), 6, 1, DATE_SUB(@ref_now, INTERVAL 89 DAY), DATE_SUB(@ref_now, INTERVAL 7 DAY), NULL),
(51, 2, 21, 'What is the Decorator Design Pattern?', 'A structural pattern that dynamically attaches additional responsibilities to an object by wrapping it without modifying its class code.', 16, DATE_ADD(@ref_now, INTERVAL 12 DAY), 4, 0, DATE_SUB(@ref_now, INTERVAL 64 DAY), DATE_SUB(@ref_now, INTERVAL 4 DAY), NULL),
(52, 2, 22, 'What is the role of Access Modifiers (public, private, protected)?', 'public: accessible everywhere; private: accessible only within the declaring class; protected: accessible within the class and its subclasses.', 8, DATE_SUB(@ref_now, INTERVAL 1 DAY), 5, 1, DATE_SUB(@ref_now, INTERVAL 49 DAY), DATE_SUB(@ref_now, INTERVAL 9 DAY), NULL),
(53, 2, 23, 'What is a Static Method / Property?', 'A member that belongs to the class type itself rather than to any specific object instance.', 8, DATE_ADD(@ref_now, INTERVAL 5 DAY), 5, 1, DATE_SUB(@ref_now, INTERVAL 39 DAY), DATE_SUB(@ref_now, INTERVAL 3 DAY), NULL),
(54, 2, 24, 'What is Dynamic (Late) Binding?', 'Resolving which polymorphic method implementation to invoke at runtime based on the actual object type rather than the reference type.', 4, DATE_SUB(@ref_now, INTERVAL 1 DAY), 2, 0, DATE_SUB(@ref_now, INTERVAL 21 DAY), DATE_SUB(@ref_now, INTERVAL 5 DAY), NULL),
(55, 2, 25, 'What is the Diamond Problem in Multiple Inheritance?', 'Ambiguity that arises when a class inherits from two classes that both inherit from a single common superclass.', 2, DATE_ADD(@ref_now, INTERVAL 1 DAY), 3, 1, DATE_SUB(@ref_now, INTERVAL 17 DAY), DATE_SUB(@ref_now, INTERVAL 1 DAY), NULL),
(56, 2, 26, 'What is Dependency Injection (DI)?', 'A technique where an object receives its required dependencies from an external source (constructor, setter, or DI container) rather than instantiating them internally.', 2, DATE_ADD(@ref_now, INTERVAL 2 DAY), 1, 0, DATE_SUB(@ref_now, INTERVAL 10 DAY), DATE_SUB(@ref_now, INTERVAL 0 DAY), NULL),
(57, 2, 27, 'What is Coupling vs. Cohesion?', 'Coupling measures interdependence between modules (aim for low); Cohesion measures how strongly related the responsibilities of a single module are (aim for high).', 1, DATE_ADD(@ref_now, INTERVAL 0 DAY), 3, 2, DATE_SUB(@ref_now, INTERVAL 14 DAY), DATE_SUB(@ref_now, INTERVAL 1 DAY), NULL),
(58, 2, 28, 'What is a Shallow Copy vs. a Deep Copy?', 'A shallow copy duplicates top-level fields and shares references to nested objects; a deep copy recursively duplicates all referenced objects.', 1, DATE_ADD(@ref_now, INTERVAL 0 DAY), 0, 0, DATE_SUB(@ref_now, INTERVAL 3 DAY), DATE_SUB(@ref_now, INTERVAL 3 DAY), NULL),
(59, 2, 29, 'What is the Law of Demeter (Principle of Least Knowledge)?', 'An object should only call methods of its immediate collaborators (\'talk only to your immediate friends, not to strangers\').', 1, DATE_ADD(@ref_now, INTERVAL 0 DAY), 0, 0, DATE_SUB(@ref_now, INTERVAL 1 DAY), DATE_SUB(@ref_now, INTERVAL 1 DAY), NULL),
(60, 2, 30, 'What is an Immutable Object?', 'An object whose internal state cannot be modified after it is constructed (e.g., String in Java/C#).', 8, DATE_SUB(@ref_now, INTERVAL 110 DAY), 5, 1, DATE_SUB(@ref_now, INTERVAL 159 DAY), DATE_SUB(@ref_now, INTERVAL 15 DAY), DATE_SUB(@ref_now, INTERVAL 15 DAY)),
(61, 3, 1, 'What does Big-O notation O(f(n)) represent?', 'An asymptotic upper bound on the growth rate of an algorithm\'s time or space complexity as input size n approaches infinity.', 256, DATE_ADD(@ref_now, INTERVAL 213 DAY), 8, 0, DATE_SUB(@ref_now, INTERVAL 300 DAY), DATE_SUB(@ref_now, INTERVAL 43 DAY), NULL),
(62, 3, 2, 'What is the average and worst-case time complexity of Binary Search?', 'O(log n) for both average and worst-case on a sorted array, with O(1) iterative space.', 256, DATE_ADD(@ref_now, INTERVAL 215 DAY), 8, 0, DATE_SUB(@ref_now, INTERVAL 296 DAY), DATE_SUB(@ref_now, INTERVAL 41 DAY), NULL),
(63, 3, 3, 'Compare Array vs. Doubly Linked List time complexities.', 'Array has O(1) random access and O(n) middle insertion; Doubly Linked List has O(n) search and O(1) insertion/deletion given a node pointer.', 128, DATE_SUB(@ref_now, INTERVAL 2 DAY), 7, 0, DATE_SUB(@ref_now, INTERVAL 258 DAY), DATE_SUB(@ref_now, INTERVAL 130 DAY), NULL),
(64, 3, 4, 'What principle does a Stack follow and what are its core operations?', 'LIFO (Last-In, First-Out) with push(), pop(), and peek() all operating in O(1) time.', 128, DATE_ADD(@ref_now, INTERVAL 78 DAY), 9, 1, DATE_SUB(@ref_now, INTERVAL 278 DAY), DATE_SUB(@ref_now, INTERVAL 50 DAY), NULL),
(65, 3, 5, 'What principle does a Queue follow and what are its core operations?', 'FIFO (First-In, First-Out) with enqueue() and dequeue() operating in O(1) time.', 128, DATE_ADD(@ref_now, INTERVAL 95 DAY), 7, 0, DATE_SUB(@ref_now, INTERVAL 238 DAY), DATE_SUB(@ref_now, INTERVAL 33 DAY), NULL),
(66, 3, 6, 'How does a Hash Table resolve collisions?', 'Primarily through Separate Chaining (linked lists/buckets at each index) or Open Addressing (Linear Probing, Quadratic Probing, Double Hashing).', 64, DATE_SUB(@ref_now, INTERVAL 4 DAY), 6, 0, DATE_SUB(@ref_now, INTERVAL 193 DAY), DATE_SUB(@ref_now, INTERVAL 68 DAY), NULL),
(67, 3, 7, 'What is the average and worst-case time complexity of Quicksort?', 'Average-case O(n log n) and worst-case O(n^2) (when pivot selection repeatedly picks extremes), with O(log n) in-place stack space.', 64, DATE_ADD(@ref_now, INTERVAL 39 DAY), 8, 1, DATE_SUB(@ref_now, INTERVAL 223 DAY), DATE_SUB(@ref_now, INTERVAL 25 DAY), NULL),
(68, 3, 8, 'What is the time and space complexity of Merge Sort?', 'O(n log n) time in best, average, and worst cases, with O(n) auxiliary space.', 64, DATE_ADD(@ref_now, INTERVAL 46 DAY), 6, 0, DATE_SUB(@ref_now, INTERVAL 163 DAY), DATE_SUB(@ref_now, INTERVAL 18 DAY), NULL),
(69, 3, 9, 'What is the defining property of a Binary Search Tree (BST)?', 'For every node N, all keys in its left subtree are strictly less than N\'s key, and all keys in its right subtree are strictly greater.', 64, DATE_ADD(@ref_now, INTERVAL 52 DAY), 10, 2, DATE_SUB(@ref_now, INTERVAL 268 DAY), DATE_SUB(@ref_now, INTERVAL 12 DAY), NULL),
(70, 3, 10, 'What are the three main Depth-First Traversals of a Binary Tree?', 'In-order (Left, Root, Right), Pre-order (Root, Left, Right), and Post-order (Left, Right, Root).', 64, DATE_SUB(@ref_now, INTERVAL 1 DAY), 6, 0, DATE_SUB(@ref_now, INTERVAL 178 DAY), DATE_SUB(@ref_now, INTERVAL 65 DAY), NULL),
(71, 3, 11, 'How does Breadth-First Search (BFS) traverse a graph?', 'It explores vertices level-by-level in order of distance from the source using a FIFO Queue in O(V + E) time.', 64, DATE_ADD(@ref_now, INTERVAL 29 DAY), 6, 0, DATE_SUB(@ref_now, INTERVAL 153 DAY), DATE_SUB(@ref_now, INTERVAL 35 DAY), NULL),
(72, 3, 12, 'How does Depth-First Search (DFS) traverse a graph?', 'It explores as far as possible along each branch before backtracking, using recursion or an explicit LIFO Stack in O(V + E) time.', 32, DATE_SUB(@ref_now, INTERVAL 3 DAY), 5, 0, DATE_SUB(@ref_now, INTERVAL 138 DAY), DATE_SUB(@ref_now, INTERVAL 35 DAY), NULL),
(73, 3, 13, 'What is an AVL Tree?', 'A self-balancing Binary Search Tree where the heights of the left and right subtrees of any node differ by at most 1 (balance factor in {-1, 0, 1}).', 32, DATE_ADD(@ref_now, INTERVAL 18 DAY), 7, 1, DATE_SUB(@ref_now, INTERVAL 148 DAY), DATE_SUB(@ref_now, INTERVAL 14 DAY), NULL),
(74, 3, 14, 'What is a Binary Heap and its main application?', 'A complete binary tree satisfying the heap-order property (Min-Heap or Max-Heap), commonly used to implement Priority Queues and Heapsort.', 32, DATE_ADD(@ref_now, INTERVAL 22 DAY), 5, 0, DATE_SUB(@ref_now, INTERVAL 128 DAY), DATE_SUB(@ref_now, INTERVAL 10 DAY), NULL),
(75, 3, 15, 'What is Dijkstra\'s Algorithm and what restriction does it have?', 'A greedy algorithm that finds shortest paths from a source vertex to all other vertices in a graph with non-negative edge weights.', 32, DATE_ADD(@ref_now, INTERVAL 0 DAY), 7, 1, DATE_SUB(@ref_now, INTERVAL 143 DAY), DATE_SUB(@ref_now, INTERVAL 32 DAY), NULL),
(76, 3, 16, 'How does the Bellman-Ford Algorithm differ from Dijkstra\'s?', 'Bellman-Ford handles negative edge weights and detects negative weight cycles in O(V * E) time.', 32, DATE_ADD(@ref_now, INTERVAL 11 DAY), 5, 0, DATE_SUB(@ref_now, INTERVAL 123 DAY), DATE_SUB(@ref_now, INTERVAL 21 DAY), NULL),
(77, 3, 17, 'What are the two core properties required for Dynamic Programming?', 'Optimal Substructure and Overlapping Subproblems.', 32, DATE_ADD(@ref_now, INTERVAL 25 DAY), 9, 2, DATE_SUB(@ref_now, INTERVAL 173 DAY), DATE_SUB(@ref_now, INTERVAL 7 DAY), NULL),
(78, 3, 18, 'Differentiate between Memoization and Tabulation in Dynamic Programming.', 'Memoization is top-down recursion with caching; Tabulation is bottom-up iterative table filling.', 32, DATE_ADD(@ref_now, INTERVAL 16 DAY), 5, 0, DATE_SUB(@ref_now, INTERVAL 118 DAY), DATE_SUB(@ref_now, INTERVAL 16 DAY), NULL),
(79, 3, 19, 'What is a Trie (Prefix Tree)?', 'A tree-like data structure used to store associative string keys where nodes share common prefixes, enabling O(L) prefix lookups.', 16, DATE_SUB(@ref_now, INTERVAL 2 DAY), 4, 0, DATE_SUB(@ref_now, INTERVAL 83 DAY), DATE_SUB(@ref_now, INTERVAL 18 DAY), NULL),
(80, 3, 20, 'What is Topological Sorting and what kind of graph requires it?', 'A linear ordering of vertices such that for every directed edge u -> v, u comes before v; only possible on a Directed Acyclic Graph (DAG).', 16, DATE_ADD(@ref_now, INTERVAL 9 DAY), 6, 1, DATE_SUB(@ref_now, INTERVAL 88 DAY), DATE_SUB(@ref_now, INTERVAL 7 DAY), NULL),
(81, 3, 21, 'What do Kruskal\'s and Prim\'s algorithms compute?', 'Both are greedy algorithms that find a Minimum Spanning Tree (MST) of a connected, undirected, weighted graph.', 16, DATE_ADD(@ref_now, INTERVAL 12 DAY), 4, 0, DATE_SUB(@ref_now, INTERVAL 63 DAY), DATE_SUB(@ref_now, INTERVAL 4 DAY), NULL),
(82, 3, 22, 'What is a Disjoint-Set (Union-Find) data structure?', 'A structure that tracks elements partitioned into non-overlapping subsets, supporting near-O(1) union and find operations via path compression and union by rank.', 8, DATE_SUB(@ref_now, INTERVAL 1 DAY), 5, 1, DATE_SUB(@ref_now, INTERVAL 48 DAY), DATE_SUB(@ref_now, INTERVAL 9 DAY), NULL),
(83, 3, 23, 'What is Amortized Time Complexity (e.g., in Dynamic Arrays)?', 'The average time per operation over a worst-case sequence of operations; appending to a dynamic array is O(1) amortized despite occasional O(n) resizing.', 8, DATE_ADD(@ref_now, INTERVAL 5 DAY), 5, 1, DATE_SUB(@ref_now, INTERVAL 38 DAY), DATE_SUB(@ref_now, INTERVAL 3 DAY), NULL),
(84, 3, 24, 'What makes a Sorting Algorithm \'Stable\'?', 'A sorting algorithm is stable if elements with equal keys maintain their relative original input order in the sorted output (e.g., Merge Sort, Insertion Sort).', 4, DATE_SUB(@ref_now, INTERVAL 1 DAY), 2, 0, DATE_SUB(@ref_now, INTERVAL 20 DAY), DATE_SUB(@ref_now, INTERVAL 5 DAY), NULL),
(85, 3, 25, 'When is Insertion Sort preferred over O(n log n) algorithms?', 'When the input size is very small or when the array is already substantially sorted (where Insertion Sort runs in near O(n) time).', 2, DATE_ADD(@ref_now, INTERVAL 1 DAY), 3, 1, DATE_SUB(@ref_now, INTERVAL 16 DAY), DATE_SUB(@ref_now, INTERVAL 1 DAY), NULL),
(86, 3, 26, 'Compare Adjacency Matrix vs. Adjacency List for graph representation.', 'Adjacency Matrix uses O(V^2) space with O(1) edge lookup; Adjacency List uses O(V + E) space and is far more efficient for sparse graphs.', 2, DATE_ADD(@ref_now, INTERVAL 2 DAY), 1, 0, DATE_SUB(@ref_now, INTERVAL 10 DAY), DATE_SUB(@ref_now, INTERVAL 0 DAY), NULL),
(87, 3, 27, 'How does Floyd\'s Cycle-Finding (Tortoise and Hare) algorithm work?', 'Uses two pointers moving at different speeds (1 step vs. 2 steps); if a cycle exists in a linked list, the fast pointer will eventually meet the slow pointer in O(n) time and O(1) space.', 1, DATE_ADD(@ref_now, INTERVAL 0 DAY), 3, 2, DATE_SUB(@ref_now, INTERVAL 14 DAY), DATE_SUB(@ref_now, INTERVAL 1 DAY), NULL),
(88, 3, 28, 'What is the Sliding Window technique?', 'An optimization pattern that maintains a dynamic subarray/substring window over contiguous data to reduce nested O(n^2) loops to O(n).', 1, DATE_ADD(@ref_now, INTERVAL 0 DAY), 0, 0, DATE_SUB(@ref_now, INTERVAL 3 DAY), DATE_SUB(@ref_now, INTERVAL 3 DAY), NULL),
(89, 3, 29, 'What is Backtracking?', 'An algorithmic paradigm that builds candidates for solutions incrementally and abandons a candidate (\'backtracks\') as soon as it determines the candidate cannot lead to a valid solution.', 1, DATE_ADD(@ref_now, INTERVAL 0 DAY), 0, 0, DATE_SUB(@ref_now, INTERVAL 1 DAY), DATE_SUB(@ref_now, INTERVAL 1 DAY), NULL),
(90, 3, 30, 'What is the Master Theorem used for?', 'Determining the asymptotic time complexity of divide-and-conquer recurrence relations of the form T(n) = aT(n/b) + f(n).', 8, DATE_SUB(@ref_now, INTERVAL 110 DAY), 5, 1, DATE_SUB(@ref_now, INTERVAL 158 DAY), DATE_SUB(@ref_now, INTERVAL 15 DAY), DATE_SUB(@ref_now, INTERVAL 15 DAY)),
(91, 4, 1, 'What is the Triple Constraint (Iron Triangle) in Project Management?', 'Scope, Time (Schedule), and Cost (Budget), which collectively impact Project Quality.', 256, DATE_ADD(@ref_now, INTERVAL 214 DAY), 8, 0, DATE_SUB(@ref_now, INTERVAL 300 DAY), DATE_SUB(@ref_now, INTERVAL 42 DAY), NULL),
(92, 4, 2, 'What are the five PMBOK Process Groups?', 'Initiating, Planning, Executing, Monitoring and Controlling, and Closing.', 256, DATE_ADD(@ref_now, INTERVAL 216 DAY), 8, 0, DATE_SUB(@ref_now, INTERVAL 295 DAY), DATE_SUB(@ref_now, INTERVAL 40 DAY), NULL),
(93, 4, 3, 'What is a Project Charter?', 'A formal document issued by the project sponsor that authorizes the existence of a project and grants the project manager authority to apply organizational resources.', 128, DATE_SUB(@ref_now, INTERVAL 2 DAY), 7, 0, DATE_SUB(@ref_now, INTERVAL 257 DAY), DATE_SUB(@ref_now, INTERVAL 130 DAY), NULL),
(94, 4, 4, 'What is a Work Breakdown Structure (WBS)?', 'A hierarchical, deliverable-oriented decomposition of the total scope of work to be carried out by the project team.', 128, DATE_ADD(@ref_now, INTERVAL 78 DAY), 9, 1, DATE_SUB(@ref_now, INTERVAL 277 DAY), DATE_SUB(@ref_now, INTERVAL 50 DAY), NULL),
(95, 4, 5, 'What is the Critical Path Method (CPM)?', 'A schedule network analysis technique that identifies the longest sequence of dependent activities determining the shortest possible project duration.', 128, DATE_ADD(@ref_now, INTERVAL 95 DAY), 7, 0, DATE_SUB(@ref_now, INTERVAL 237 DAY), DATE_SUB(@ref_now, INTERVAL 33 DAY), NULL),
(96, 4, 6, 'What is Total Float (Slack) in project scheduling?', 'The amount of time a schedule activity can be delayed from its early start date without delaying the project finish date.', 64, DATE_SUB(@ref_now, INTERVAL 4 DAY), 6, 0, DATE_SUB(@ref_now, INTERVAL 192 DAY), DATE_SUB(@ref_now, INTERVAL 68 DAY), NULL),
(97, 4, 7, 'In Earned Value Management (EVM), what are PV, EV, and AC?', 'Planned Value (PV: budgeted cost of work scheduled), Earned Value (EV: budgeted cost of work performed), and Actual Cost (AC: actual cost incurred).', 64, DATE_ADD(@ref_now, INTERVAL 39 DAY), 8, 1, DATE_SUB(@ref_now, INTERVAL 222 DAY), DATE_SUB(@ref_now, INTERVAL 25 DAY), NULL),
(98, 4, 8, 'How is Schedule Performance Index (SPI) calculated and interpreted?', 'SPI = EV / PV. An SPI < 1.0 indicates the project is behind schedule; SPI > 1.0 indicates it is ahead of schedule.', 64, DATE_ADD(@ref_now, INTERVAL 46 DAY), 6, 0, DATE_SUB(@ref_now, INTERVAL 162 DAY), DATE_SUB(@ref_now, INTERVAL 18 DAY), NULL),
(99, 4, 9, 'How is Cost Performance Index (CPI) calculated and interpreted?', 'CPI = EV / AC. A CPI < 1.0 indicates the project is over budget; CPI > 1.0 indicates it is under budget.', 64, DATE_ADD(@ref_now, INTERVAL 52 DAY), 10, 2, DATE_SUB(@ref_now, INTERVAL 267 DAY), DATE_SUB(@ref_now, INTERVAL 12 DAY), NULL),
(100, 4, 10, 'What is Scope Creep?', 'The uncontrolled expansion of product or project scope without adjustments to time, cost, and resources, or without formal change approval.', 64, DATE_SUB(@ref_now, INTERVAL 1 DAY), 6, 0, DATE_SUB(@ref_now, INTERVAL 177 DAY), DATE_SUB(@ref_now, INTERVAL 65 DAY), NULL),
(101, 4, 11, 'What is a RACI Matrix?', 'A responsibility assignment matrix mapping activities to roles: Responsible, Accountable, Consulted, and Informed.', 64, DATE_ADD(@ref_now, INTERVAL 29 DAY), 6, 0, DATE_SUB(@ref_now, INTERVAL 152 DAY), DATE_SUB(@ref_now, INTERVAL 35 DAY), NULL),
(102, 4, 12, 'What are the three pillars of Empirical Process Control in Scrum?', 'Transparency, Inspection, and Adaptation.', 32, DATE_SUB(@ref_now, INTERVAL 3 DAY), 5, 0, DATE_SUB(@ref_now, INTERVAL 137 DAY), DATE_SUB(@ref_now, INTERVAL 35 DAY), NULL),
(103, 4, 13, 'What are the three accountabilities (roles) in a Scrum Team?', 'Product Owner, Scrum Master, and Developers.', 32, DATE_ADD(@ref_now, INTERVAL 18 DAY), 7, 1, DATE_SUB(@ref_now, INTERVAL 147 DAY), DATE_SUB(@ref_now, INTERVAL 14 DAY), NULL),
(104, 4, 14, 'What are the five formal events in Scrum?', 'The Sprint, Sprint Planning, Daily Scrum, Sprint Review, and Sprint Retrospective.', 32, DATE_ADD(@ref_now, INTERVAL 22 DAY), 5, 0, DATE_SUB(@ref_now, INTERVAL 127 DAY), DATE_SUB(@ref_now, INTERVAL 10 DAY), NULL),
(105, 4, 15, 'Differentiate between the Product Backlog and the Sprint Backlog.', 'The Product Backlog is an ordered list of everything needed in the product; the Sprint Backlog is the subset of items selected for the current Sprint plus the plan for delivering them.', 32, DATE_ADD(@ref_now, INTERVAL 0 DAY), 7, 1, DATE_SUB(@ref_now, INTERVAL 142 DAY), DATE_SUB(@ref_now, INTERVAL 32 DAY), NULL),
(106, 4, 16, 'What is a Risk Register?', 'A project document recording identified risks, their probability, impact severity, risk owners, and planned mitigation/response strategies.', 32, DATE_ADD(@ref_now, INTERVAL 11 DAY), 5, 0, DATE_SUB(@ref_now, INTERVAL 122 DAY), DATE_SUB(@ref_now, INTERVAL 21 DAY), NULL),
(107, 4, 17, 'What are the four common strategies for managing Negative Risks (Threats)?', 'Avoid, Mitigate, Transfer, and Accept (plus Escalate in newer PMBOK editions).', 32, DATE_ADD(@ref_now, INTERVAL 25 DAY), 9, 2, DATE_SUB(@ref_now, INTERVAL 172 DAY), DATE_SUB(@ref_now, INTERVAL 7 DAY), NULL),
(108, 4, 18, 'What is a Gantt Chart?', 'A horizontal bar chart illustrating a project schedule, showing activity start/end dates, durations, milestones, and dependencies.', 32, DATE_ADD(@ref_now, INTERVAL 16 DAY), 5, 0, DATE_SUB(@ref_now, INTERVAL 117 DAY), DATE_SUB(@ref_now, INTERVAL 16 DAY), NULL),
(109, 4, 19, 'Compare Waterfall vs. Agile project methodologies.', 'Waterfall is a linear, predictive approach with upfront requirements; Agile is an iterative, incremental, and adaptive approach embracing change.', 16, DATE_SUB(@ref_now, INTERVAL 2 DAY), 4, 0, DATE_SUB(@ref_now, INTERVAL 82 DAY), DATE_SUB(@ref_now, INTERVAL 18 DAY), NULL),
(110, 4, 20, 'What is Kanban and its core practice regarding Work in Progress (WIP)?', 'A visual workflow management method that limits Work in Progress (WIP) at each stage to eliminate bottlenecks and maximize flow.', 16, DATE_ADD(@ref_now, INTERVAL 9 DAY), 6, 1, DATE_SUB(@ref_now, INTERVAL 87 DAY), DATE_SUB(@ref_now, INTERVAL 7 DAY), NULL),
(111, 4, 21, 'What is a Stakeholder Power/Interest Grid?', 'A classification tool that groups stakeholders by their level of authority (Power) and concern (Interest) to determine management strategies (e.g., Manage Closely, Keep Informed).', 16, DATE_ADD(@ref_now, INTERVAL 12 DAY), 4, 0, DATE_SUB(@ref_now, INTERVAL 62 DAY), DATE_SUB(@ref_now, INTERVAL 4 DAY), NULL),
(112, 4, 22, 'What is the Definition of Done (DoD) in Agile?', 'A formal, shared quality checklist of criteria that a product increment must meet to be considered complete and potentially releasable.', 8, DATE_SUB(@ref_now, INTERVAL 1 DAY), 5, 1, DATE_SUB(@ref_now, INTERVAL 47 DAY), DATE_SUB(@ref_now, INTERVAL 9 DAY), NULL),
(113, 4, 23, 'What is Sprint Velocity?', 'A metric measuring the average amount of work (often in Story Points) a Scrum team completes during a single Sprint.', 8, DATE_ADD(@ref_now, INTERVAL 5 DAY), 5, 1, DATE_SUB(@ref_now, INTERVAL 37 DAY), DATE_SUB(@ref_now, INTERVAL 3 DAY), NULL),
(114, 4, 24, 'Differentiate between a Burndown Chart and a Burnup Chart.', 'A Burndown chart plots work remaining against time; a Burnup chart plots completed work alongside a separate total scope line, making scope changes visible.', 4, DATE_SUB(@ref_now, INTERVAL 1 DAY), 2, 0, DATE_SUB(@ref_now, INTERVAL 19 DAY), DATE_SUB(@ref_now, INTERVAL 5 DAY), NULL),
(115, 4, 25, 'What is a Change Control Board (CCB)?', 'A formally constituted group of stakeholders responsible for reviewing, evaluating, approving, delaying, or rejecting changes to project baselines.', 2, DATE_ADD(@ref_now, INTERVAL 1 DAY), 3, 1, DATE_SUB(@ref_now, INTERVAL 15 DAY), DATE_SUB(@ref_now, INTERVAL 1 DAY), NULL),
(116, 4, 26, 'What is Gold Plating in project management?', 'Adding extra features or functionality that were not requested by the customer, introducing unnecessary risk and cost without adding approved value.', 2, DATE_ADD(@ref_now, INTERVAL 2 DAY), 1, 0, DATE_SUB(@ref_now, INTERVAL 10 DAY), DATE_SUB(@ref_now, INTERVAL 0 DAY), NULL),
(117, 4, 27, 'Differentiate between Fast Tracking and Crashing in schedule compression.', 'Fast Tracking performs sequential critical path activities in parallel (increases rework risk); Crashing adds extra resources to shorten duration (increases cost).', 1, DATE_ADD(@ref_now, INTERVAL 0 DAY), 3, 2, DATE_SUB(@ref_now, INTERVAL 14 DAY), DATE_SUB(@ref_now, INTERVAL 1 DAY), NULL),
(118, 4, 28, 'What is a Lessons Learned Register?', 'A document capturing knowledge gained during a project so future projects can replicate successes and avoid past mistakes.', 1, DATE_ADD(@ref_now, INTERVAL 0 DAY), 0, 0, DATE_SUB(@ref_now, INTERVAL 3 DAY), DATE_SUB(@ref_now, INTERVAL 3 DAY), NULL),
(119, 4, 29, 'What is a Minimum Viable Product (MVP)?', 'A version of a new product with just enough core features to be usable by early customers who can then provide validated feedback for future development.', 1, DATE_ADD(@ref_now, INTERVAL 0 DAY), 0, 0, DATE_SUB(@ref_now, INTERVAL 1 DAY), DATE_SUB(@ref_now, INTERVAL 1 DAY), NULL),
(120, 4, 30, 'What is Technical Debt?', 'The implied cost of future refactoring and rework caused by choosing a quick, suboptimal software design or implementation now instead of a better approach.', 8, DATE_SUB(@ref_now, INTERVAL 110 DAY), 5, 1, DATE_SUB(@ref_now, INTERVAL 157 DAY), DATE_SUB(@ref_now, INTERVAL 15 DAY), DATE_SUB(@ref_now, INTERVAL 15 DAY)),
(121, 5, 1, 'What is the derivative of f(x) = x^n with respect to x (Power Rule)?', 'f\'(x) = n * x^(n - 1).', 256, DATE_ADD(@ref_now, INTERVAL 215 DAY), 8, 0, DATE_SUB(@ref_now, INTERVAL 300 DAY), DATE_SUB(@ref_now, INTERVAL 41 DAY), NULL),
(122, 5, 2, 'State the Fundamental Theorem of Calculus (Part 1 & 2).', 'Differentiation and definite integration are inverse operations: if F\'(x) = f(x), then the definite integral of f(x) from a to b equals F(b) - F(a).', 256, DATE_ADD(@ref_now, INTERVAL 217 DAY), 8, 0, DATE_SUB(@ref_now, INTERVAL 294 DAY), DATE_SUB(@ref_now, INTERVAL 39 DAY), NULL),
(123, 5, 3, 'State Bayes\' Theorem in probability.', 'P(A|B) = [P(B|A) * P(A)] / P(B), relating conditional and marginal probabilities of events A and B.', 128, DATE_SUB(@ref_now, INTERVAL 2 DAY), 7, 0, DATE_SUB(@ref_now, INTERVAL 256 DAY), DATE_SUB(@ref_now, INTERVAL 130 DAY), NULL),
(124, 5, 4, 'What are De Morgan\'s Laws in propositional logic?', 'NOT (P AND Q) is equivalent to (NOT P) OR (NOT Q); NOT (P OR Q) is equivalent to (NOT P) AND (NOT Q).', 128, DATE_ADD(@ref_now, INTERVAL 78 DAY), 9, 1, DATE_SUB(@ref_now, INTERVAL 276 DAY), DATE_SUB(@ref_now, INTERVAL 50 DAY), NULL),
(125, 5, 5, 'When is a square matrix A invertible (non-singular)?', 'A square matrix A is invertible if and only if its determinant det(A) is non-zero (i.e., its columns/rows are linearly independent).', 128, DATE_ADD(@ref_now, INTERVAL 95 DAY), 7, 0, DATE_SUB(@ref_now, INTERVAL 236 DAY), DATE_SUB(@ref_now, INTERVAL 33 DAY), NULL),
(126, 5, 6, 'Define Eigenvalues and Eigenvectors of a square matrix A.', 'A non-zero vector v is an eigenvector of A with scalar eigenvalue lambda if A*v = lambda*v.', 64, DATE_SUB(@ref_now, INTERVAL 4 DAY), 6, 0, DATE_SUB(@ref_now, INTERVAL 191 DAY), DATE_SUB(@ref_now, INTERVAL 68 DAY), NULL),
(127, 5, 7, 'What is the difference between Permutations and Combinations?', 'Permutations P(n, r) = n! / (n - r)! count ordered arrangements; Combinations C(n, r) = n! / [r!(n - r)!] count unordered selections.', 64, DATE_ADD(@ref_now, INTERVAL 39 DAY), 8, 1, DATE_SUB(@ref_now, INTERVAL 221 DAY), DATE_SUB(@ref_now, INTERVAL 25 DAY), NULL),
(128, 5, 8, 'State the Pigeonhole Principle.', 'If n items are put into m containers with n > m, then at least one container must contain more than one item.', 64, DATE_ADD(@ref_now, INTERVAL 46 DAY), 6, 0, DATE_SUB(@ref_now, INTERVAL 161 DAY), DATE_SUB(@ref_now, INTERVAL 18 DAY), NULL),
(129, 5, 9, 'What is Mathematical Induction?', 'A proof technique that establishes a base case P(1) and proves the inductive step that P(k) implies P(k + 1) for all k >= 1.', 64, DATE_ADD(@ref_now, INTERVAL 52 DAY), 10, 2, DATE_SUB(@ref_now, INTERVAL 266 DAY), DATE_SUB(@ref_now, INTERVAL 12 DAY), NULL),
(130, 5, 10, 'In Modular Arithmetic, what does \'a is congruent to b (mod m)\' mean?', 'It means that m evenly divides the difference (a - b), or equivalently, a and b leave the same remainder when divided by m.', 64, DATE_SUB(@ref_now, INTERVAL 1 DAY), 6, 0, DATE_SUB(@ref_now, INTERVAL 176 DAY), DATE_SUB(@ref_now, INTERVAL 65 DAY), NULL),
(131, 5, 11, 'What is the formula for the Dot Product of two vectors u and v?', 'u . v = sum(u_i * v_i) = ||u|| * ||v|| * cos(theta), where theta is the angle between the vectors.', 64, DATE_ADD(@ref_now, INTERVAL 29 DAY), 6, 0, DATE_SUB(@ref_now, INTERVAL 151 DAY), DATE_SUB(@ref_now, INTERVAL 35 DAY), NULL),
(132, 5, 12, 'What is the Chain Rule for derivatives?', 'If y = f(g(x)), then dy/dx = f\'(g(x)) * g\'(x).', 32, DATE_SUB(@ref_now, INTERVAL 3 DAY), 5, 0, DATE_SUB(@ref_now, INTERVAL 136 DAY), DATE_SUB(@ref_now, INTERVAL 35 DAY), NULL),
(133, 5, 13, 'How do you find the sum of an infinite Geometric Series a + ar + ar^2 + ...?', 'If |r| < 1, the series converges to S = a / (1 - r); if |r| >= 1, the series diverges.', 32, DATE_ADD(@ref_now, INTERVAL 18 DAY), 7, 1, DATE_SUB(@ref_now, INTERVAL 146 DAY), DATE_SUB(@ref_now, INTERVAL 14 DAY), NULL),
(134, 5, 14, 'What is the contrapositive of the conditional statement \'If P, then Q\' (P -> Q)?', '\'If NOT Q, then NOT P\' (~Q -> ~P), which is logically equivalent to the original implication.', 32, DATE_ADD(@ref_now, INTERVAL 22 DAY), 5, 0, DATE_SUB(@ref_now, INTERVAL 126 DAY), DATE_SUB(@ref_now, INTERVAL 10 DAY), NULL),
(135, 5, 15, 'Define a Bijective Function (Bijection).', 'A function f: A -> B that is both Injective (one-to-one) and Surjective (onto), guaranteeing that an inverse function f^(-1) exists.', 32, DATE_ADD(@ref_now, INTERVAL 0 DAY), 7, 1, DATE_SUB(@ref_now, INTERVAL 141 DAY), DATE_SUB(@ref_now, INTERVAL 32 DAY), NULL),
(136, 5, 16, 'What are the three properties of an Equivalence Relation?', 'Reflexivity (a ~ a), Symmetry (if a ~ b then b ~ a), and Transitivity (if a ~ b and b ~ c then a ~ c).', 32, DATE_ADD(@ref_now, INTERVAL 11 DAY), 5, 0, DATE_SUB(@ref_now, INTERVAL 121 DAY), DATE_SUB(@ref_now, INTERVAL 21 DAY), NULL),
(137, 5, 17, 'State Euler\'s Formula for connected planar graphs.', 'V - E + F = 2, where V is the number of vertices, E is the number of edges, and F is the number of faces (including the exterior face).', 32, DATE_ADD(@ref_now, INTERVAL 25 DAY), 9, 2, DATE_SUB(@ref_now, INTERVAL 171 DAY), DATE_SUB(@ref_now, INTERVAL 7 DAY), NULL),
(138, 5, 18, 'What are the Mean and Variance of a Binomial Distribution B(n, p)?', 'Mean (expected value) E[X] = n * p, and Variance Var(X) = n * p * (1 - p).', 32, DATE_ADD(@ref_now, INTERVAL 16 DAY), 5, 0, DATE_SUB(@ref_now, INTERVAL 116 DAY), DATE_SUB(@ref_now, INTERVAL 16 DAY), NULL),
(139, 5, 19, 'What does the Central Limit Theorem (CLT) state?', 'The sampling distribution of the sample mean of independent random variables approaches a Normal Distribution as sample size n grows large, regardless of the population\'s original distribution.', 16, DATE_SUB(@ref_now, INTERVAL 2 DAY), 4, 0, DATE_SUB(@ref_now, INTERVAL 81 DAY), DATE_SUB(@ref_now, INTERVAL 18 DAY), NULL),
(140, 5, 20, 'What is Integration by Parts?', 'A technique based on the product rule: integral(u dv) = u*v - integral(v du).', 16, DATE_ADD(@ref_now, INTERVAL 9 DAY), 6, 1, DATE_SUB(@ref_now, INTERVAL 86 DAY), DATE_SUB(@ref_now, INTERVAL 7 DAY), NULL),
(141, 5, 21, 'What is a Partial Derivative?', 'The derivative of a multivariable function with respect to one variable while holding all other variables constant.', 16, DATE_ADD(@ref_now, INTERVAL 12 DAY), 4, 0, DATE_SUB(@ref_now, INTERVAL 61 DAY), DATE_SUB(@ref_now, INTERVAL 4 DAY), NULL),
(142, 5, 22, 'What is the Gradient Vector grad(f) of a scalar function?', 'The vector of all partial derivatives of f, pointing in the direction of greatest rate of increase of the function.', 8, DATE_SUB(@ref_now, INTERVAL 1 DAY), 5, 1, DATE_SUB(@ref_now, INTERVAL 46 DAY), DATE_SUB(@ref_now, INTERVAL 9 DAY), NULL),
(143, 5, 23, 'What is the Rank of a Matrix?', 'The dimension of the vector space spanned by its columns (or rows), equal to the number of pivot positions in its row echelon form.', 8, DATE_ADD(@ref_now, INTERVAL 5 DAY), 5, 1, DATE_SUB(@ref_now, INTERVAL 36 DAY), DATE_SUB(@ref_now, INTERVAL 3 DAY), NULL),
(144, 5, 24, 'State Fermat\'s Little Theorem.', 'If p is a prime number and a is an integer not divisible by p, then a^(p - 1) is congruent to 1 (mod p).', 4, DATE_SUB(@ref_now, INTERVAL 1 DAY), 2, 0, DATE_SUB(@ref_now, INTERVAL 18 DAY), DATE_SUB(@ref_now, INTERVAL 5 DAY), NULL),
(145, 5, 25, 'What is the Principle of Inclusion-Exclusion for two sets A and B?', '|A union B| = |A| + |B| - |A intersect B|.', 2, DATE_ADD(@ref_now, INTERVAL 1 DAY), 3, 1, DATE_SUB(@ref_now, INTERVAL 14 DAY), DATE_SUB(@ref_now, INTERVAL 1 DAY), NULL),
(146, 5, 26, 'What is L\'Hopital\'s Rule?', 'If limit f(x)/g(x) produces an indeterminate form 0/0 or infinity/infinity, then lim [f(x)/g(x)] = lim [f\'(x)/g\'(x)] provided the latter limit exists.', 2, DATE_ADD(@ref_now, INTERVAL 2 DAY), 1, 0, DATE_SUB(@ref_now, INTERVAL 10 DAY), DATE_SUB(@ref_now, INTERVAL 0 DAY), NULL),
(147, 5, 27, 'What is the Taylor Series expansion of f(x) around x = a?', 'sum_{n=0 to infinity} [f^(n)(a) / n!] * (x - a)^n.', 1, DATE_ADD(@ref_now, INTERVAL 0 DAY), 3, 2, DATE_SUB(@ref_now, INTERVAL 14 DAY), DATE_SUB(@ref_now, INTERVAL 1 DAY), NULL),
(148, 5, 28, 'What is a Bipartite Graph?', 'A graph whose vertices can be divided into two disjoint independent sets U and V such that every edge connects a vertex in U to one in V (contains no odd-length cycles).', 1, DATE_ADD(@ref_now, INTERVAL 0 DAY), 0, 0, DATE_SUB(@ref_now, INTERVAL 3 DAY), DATE_SUB(@ref_now, INTERVAL 3 DAY), NULL),
(149, 5, 29, 'What is the determinant of a 2x2 matrix [[a, b], [c, d]]?', 'det(A) = a*d - b*c.', 1, DATE_ADD(@ref_now, INTERVAL 0 DAY), 0, 0, DATE_SUB(@ref_now, INTERVAL 1 DAY), DATE_SUB(@ref_now, INTERVAL 1 DAY), NULL),
(150, 5, 30, 'What is the difference between Mutual Exclusivity and Independence in probability?', 'Mutually exclusive events cannot occur together (P(A and B) = 0); Independent events do not affect each other\'s probability (P(A and B) = P(A) * P(B)).', 8, DATE_SUB(@ref_now, INTERVAL 110 DAY), 5, 1, DATE_SUB(@ref_now, INTERVAL 156 DAY), DATE_SUB(@ref_now, INTERVAL 15 DAY), DATE_SUB(@ref_now, INTERVAL 15 DAY)),
(151, 6, 1, 'What is the core rule of Subject-Verb Agreement with prepositional phrases?', 'A verb must agree in number with its true grammatical subject, not with nouns inside intervening prepositional phrases (e.g., \'The box of tools IS heavy\').', 256, DATE_ADD(@ref_now, INTERVAL 216 DAY), 8, 0, DATE_SUB(@ref_now, INTERVAL 300 DAY), DATE_SUB(@ref_now, INTERVAL 40 DAY), NULL),
(152, 6, 2, 'Differentiate between \'Affect\' and \'Effect\'.', '\'Affect\' is primarily a verb meaning to influence; \'Effect\' is primarily a noun meaning a result (or a verb meaning to bring about, as in \'effect change\').', 256, DATE_ADD(@ref_now, INTERVAL 218 DAY), 8, 0, DATE_SUB(@ref_now, INTERVAL 293 DAY), DATE_SUB(@ref_now, INTERVAL 38 DAY), NULL),
(153, 6, 3, 'Differentiate between Active Voice and Passive Voice.', 'In Active Voice, the subject performs the action (\'The developer wrote the code\'); in Passive Voice, the subject receives the action (\'The code was written by the developer\').', 128, DATE_SUB(@ref_now, INTERVAL 2 DAY), 7, 0, DATE_SUB(@ref_now, INTERVAL 255 DAY), DATE_SUB(@ref_now, INTERVAL 130 DAY), NULL),
(154, 6, 4, 'What is a Dangling Modifier?', 'A descriptive word or phrase that does not clearly or logically refer to the grammatical subject of the sentence that follows it.', 128, DATE_ADD(@ref_now, INTERVAL 78 DAY), 9, 1, DATE_SUB(@ref_now, INTERVAL 275 DAY), DATE_SUB(@ref_now, INTERVAL 50 DAY), NULL),
(155, 6, 5, 'What is a Comma Splice and how can it be fixed?', 'Joining two independent clauses with only a comma; fixed by using a period, a semicolon, or adding a coordinating conjunction (FANBOYS).', 128, DATE_ADD(@ref_now, INTERVAL 95 DAY), 7, 0, DATE_SUB(@ref_now, INTERVAL 235 DAY), DATE_SUB(@ref_now, INTERVAL 33 DAY), NULL),
(156, 6, 6, 'What is Parallelism (Parallel Structure) in writing?', 'Using the same grammatical form for coordinate elements in a list or comparison (e.g., \'She likes reading, writing, and coding\').', 64, DATE_SUB(@ref_now, INTERVAL 4 DAY), 6, 0, DATE_SUB(@ref_now, INTERVAL 190 DAY), DATE_SUB(@ref_now, INTERVAL 68 DAY), NULL),
(157, 6, 7, 'Define \'Ubiquitous\' and use it in context.', 'Present, appearing, or found everywhere (e.g., \'Smartphones have become ubiquitous in modern society\').', 64, DATE_ADD(@ref_now, INTERVAL 39 DAY), 8, 1, DATE_SUB(@ref_now, INTERVAL 220 DAY), DATE_SUB(@ref_now, INTERVAL 25 DAY), NULL),
(158, 6, 8, 'Define \'Ephemeral\' and use it in context.', 'Lasting for a very short time; transitory (e.g., \'Social media trends are often ephemeral\').', 64, DATE_ADD(@ref_now, INTERVAL 46 DAY), 6, 0, DATE_SUB(@ref_now, INTERVAL 160 DAY), DATE_SUB(@ref_now, INTERVAL 18 DAY), NULL),
(159, 6, 9, 'Define \'Pragmatic\' and use it in context.', 'Dealing with things sensibly and realistically in a way that is based on practical rather than theoretical considerations.', 64, DATE_ADD(@ref_now, INTERVAL 52 DAY), 10, 2, DATE_SUB(@ref_now, INTERVAL 265 DAY), DATE_SUB(@ref_now, INTERVAL 12 DAY), NULL),
(160, 6, 10, 'Define \'Equivocate\' and use it in context.', 'To use ambiguous language so as to conceal the truth or avoid committing oneself.', 64, DATE_SUB(@ref_now, INTERVAL 1 DAY), 6, 0, DATE_SUB(@ref_now, INTERVAL 175 DAY), DATE_SUB(@ref_now, INTERVAL 65 DAY), NULL),
(161, 6, 11, 'Differentiate between a Metaphor and a Simile.', 'A Simile compares two things explicitly using \'like\' or \'as\'; a Metaphor states that one thing IS another directly without \'like\' or \'as\'.', 64, DATE_ADD(@ref_now, INTERVAL 29 DAY), 6, 0, DATE_SUB(@ref_now, INTERVAL 150 DAY), DATE_SUB(@ref_now, INTERVAL 35 DAY), NULL),
(162, 6, 12, 'What are Ethos, Pathos, and Logos in rhetoric?', 'Ethos appeals to credibility/ethics; Pathos appeals to emotion; Logos appeals to logic, evidence, and reasoning.', 32, DATE_SUB(@ref_now, INTERVAL 3 DAY), 5, 0, DATE_SUB(@ref_now, INTERVAL 135 DAY), DATE_SUB(@ref_now, INTERVAL 35 DAY), NULL),
(163, 6, 13, 'When should you use \'Who\' vs. \'Whom\'?', 'Use \'Who\' as a grammatical subject (he/she/they); use \'Whom\' as the object of a verb or preposition (him/her/them).', 32, DATE_ADD(@ref_now, INTERVAL 18 DAY), 7, 1, DATE_SUB(@ref_now, INTERVAL 145 DAY), DATE_SUB(@ref_now, INTERVAL 14 DAY), NULL),
(164, 6, 14, 'Differentiate between \'Its\' and \'It\'s\'.', '\'Its\' is a possessive pronoun (\'The system lost its connection\'); \'It\'s\' is a contraction for \'it is\' or \'it has\'.', 32, DATE_ADD(@ref_now, INTERVAL 22 DAY), 5, 0, DATE_SUB(@ref_now, INTERVAL 125 DAY), DATE_SUB(@ref_now, INTERVAL 10 DAY), NULL),
(165, 6, 15, 'What is a Thesis Statement in academic writing?', 'A concise, arguable claim typically placed at the end of the introduction that states the central argument and scope of an essay.', 32, DATE_ADD(@ref_now, INTERVAL 0 DAY), 7, 1, DATE_SUB(@ref_now, INTERVAL 140 DAY), DATE_SUB(@ref_now, INTERVAL 32 DAY), NULL),
(166, 6, 16, 'What does the idiom \'Bite the bullet\' mean?', 'To face a difficult, unpleasant, or unavoidable situation with courage and determination.', 32, DATE_ADD(@ref_now, INTERVAL 11 DAY), 5, 0, DATE_SUB(@ref_now, INTERVAL 120 DAY), DATE_SUB(@ref_now, INTERVAL 21 DAY), NULL),
(167, 6, 17, 'What does the idiom \'Play devil\'s advocate\' mean?', 'To argue against an idea or take an opposing position for the sake of testing the strength of the original argument.', 32, DATE_ADD(@ref_now, INTERVAL 25 DAY), 9, 2, DATE_SUB(@ref_now, INTERVAL 170 DAY), DATE_SUB(@ref_now, INTERVAL 7 DAY), NULL),
(168, 6, 18, 'What are the First, Second, and Third Conditional structures?', 'First (real future): If + present, will + verb; Second (unreal present): If + past, would + verb; Third (unreal past): If + past perfect, would have + past participle.', 32, DATE_ADD(@ref_now, INTERVAL 16 DAY), 5, 0, DATE_SUB(@ref_now, INTERVAL 115 DAY), DATE_SUB(@ref_now, INTERVAL 16 DAY), NULL),
(169, 6, 19, 'Differentiate between a Restrictive (\'that\') and Non-Restrictive (\'which\') clause.', 'A restrictive clause (\'that\') is essential to the noun\'s identity and uses no commas; a non-restrictive clause (\'which\') adds extra info and is set off by commas.', 16, DATE_SUB(@ref_now, INTERVAL 2 DAY), 4, 0, DATE_SUB(@ref_now, INTERVAL 80 DAY), DATE_SUB(@ref_now, INTERVAL 18 DAY), NULL),
(170, 6, 20, 'What is the Subjunctive Mood in English?', 'A verb form used to express wishes, hypothetical situations, or formal demands (e.g., \'If I WERE you\' or \'The board requires that he BE present\').', 16, DATE_ADD(@ref_now, INTERVAL 9 DAY), 6, 1, DATE_SUB(@ref_now, INTERVAL 85 DAY), DATE_SUB(@ref_now, INTERVAL 7 DAY), NULL),
(171, 6, 21, 'Differentiate between \'Fewer\' and \'Less\'.', 'Use \'Fewer\' with countable plural nouns (\'fewer bugs\'); use \'Less\' with uncountable singular nouns (\'less memory\').', 16, DATE_ADD(@ref_now, INTERVAL 12 DAY), 4, 0, DATE_SUB(@ref_now, INTERVAL 60 DAY), DATE_SUB(@ref_now, INTERVAL 4 DAY), NULL),
(172, 6, 22, 'Differentiate between \'Compliment\' and \'Complement\'.', 'A \'Compliment\' is an expression of praise; a \'Complement\' is something that completes or brings to perfection (\'The UI complements the backend\').', 8, DATE_SUB(@ref_now, INTERVAL 1 DAY), 5, 1, DATE_SUB(@ref_now, INTERVAL 45 DAY), DATE_SUB(@ref_now, INTERVAL 9 DAY), NULL),
(173, 6, 23, 'Define \'Mitigate\' and use it in context.', 'To make less severe, serious, or painful (e.g., \'Backups help mitigate the impact of hardware failure\').', 8, DATE_ADD(@ref_now, INTERVAL 5 DAY), 5, 1, DATE_SUB(@ref_now, INTERVAL 35 DAY), DATE_SUB(@ref_now, INTERVAL 3 DAY), NULL),
(174, 6, 24, 'Define \'Lucid\' and use it in context.', 'Expressed clearly; easy to understand (e.g., \'The architect wrote a lucid explanation of the database schema\').', 4, DATE_SUB(@ref_now, INTERVAL 1 DAY), 2, 0, DATE_SUB(@ref_now, INTERVAL 17 DAY), DATE_SUB(@ref_now, INTERVAL 5 DAY), NULL),
(175, 6, 25, 'Define \'Alleviate\' and use it in context.', 'To make suffering, deficiency, or a problem less severe.', 2, DATE_ADD(@ref_now, INTERVAL 1 DAY), 3, 1, DATE_SUB(@ref_now, INTERVAL 13 DAY), DATE_SUB(@ref_now, INTERVAL 1 DAY), NULL),
(176, 6, 26, 'Define \'Corroborate\' and use it in context.', 'To confirm or give support to a statement, theory, or finding with independent evidence.', 2, DATE_ADD(@ref_now, INTERVAL 2 DAY), 1, 0, DATE_SUB(@ref_now, INTERVAL 10 DAY), DATE_SUB(@ref_now, INTERVAL 0 DAY), NULL),
(177, 6, 27, 'What is an Oxymoron?', 'A figure of speech in which apparently contradictory terms appear in conjunction (e.g., \'deafening silence\', \'open secret\').', 1, DATE_ADD(@ref_now, INTERVAL 0 DAY), 3, 2, DATE_SUB(@ref_now, INTERVAL 14 DAY), DATE_SUB(@ref_now, INTERVAL 1 DAY), NULL),
(178, 6, 28, 'What is Hyperbole?', 'Exaggerated statements or claims not meant to be taken literally, used for rhetorical emphasis.', 1, DATE_ADD(@ref_now, INTERVAL 0 DAY), 0, 0, DATE_SUB(@ref_now, INTERVAL 3 DAY), DATE_SUB(@ref_now, INTERVAL 3 DAY), NULL),
(179, 6, 29, 'How should a Semicolon (;) be properly used?', 'To link two closely related independent clauses without a coordinating conjunction, or to separate complex items in a list that already contain commas.', 1, DATE_ADD(@ref_now, INTERVAL 0 DAY), 0, 0, DATE_SUB(@ref_now, INTERVAL 1 DAY), DATE_SUB(@ref_now, INTERVAL 1 DAY), NULL),
(180, 6, 30, 'What is Nominalization and why should excessive use be avoided?', 'Turning active verbs or adjectives into abstract nouns (e.g., \'make a decision\' instead of \'decide\'); avoiding it makes technical writing clearer and more direct.', 8, DATE_SUB(@ref_now, INTERVAL 110 DAY), 5, 1, DATE_SUB(@ref_now, INTERVAL 155 DAY), DATE_SUB(@ref_now, INTERVAL 15 DAY), DATE_SUB(@ref_now, INTERVAL 15 DAY));
